# Turn engine_attrs.json (extract.py: the TWUI serializers of Three_Kingdoms.exe 1.7.2.0) into
# src/twui/engineAttrs.ts. Regenerate after a game update:
#   python scripts/engine_attrs/extract.py && python scripts/engine_attrs/gen_ts.py
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "engine_attrs.json")
OUT = os.path.join(HERE, "..", "..", "src", "twui", "engineAttrs.ts")

data = json.load(open(SRC))
rows = data["attributes"]
lines = [
    "// GENERATED by scripts/engine_attrs/gen_ts.py from the TWUI serializers of",
    "// %s. Do not edit by hand: re-run extract.py + gen_ts.py." % data["exe"],
    "//",
]
for n in data["notes"]:
    lines.append("// - " + n)
lines += [
    "",
    "/** One attribute the game's TWUI reader handles. `kind` is the engine object it belongs to",
    " *  (component, state, image = image metric, component_image, layoutEngine*, template_override,",
    " *  ...); `type` is the reader it goes through; `offset` is the field in the engine object when",
    " *  the extractor could see it; `default` is what the game uses when the attribute is missing",
    " *  (written the way the game writes it); `values` lists an enum's names in engine order. */",
    "export interface EngineAttr {",
    "  kind: string;",
    "  attr: string;",
    "  member: string | null;",
    "  type: string;",
    "  offset: string | null;",
    "  serializer: string;",
    "  default?: string;",
    "  values?: string[];",
    "  /** Layout versions the reader looks at this attribute in (inclusive); absent = all. */",
    "  versions?: { min?: number; max?: number };",
    "}",
    "",
    "export const ENGINE_EXE = %s;" % json.dumps(data["exe"]),
    "",
    "export const ENGINE_ATTRS: EngineAttr[] = [",
]


def fmt_default(r):
    v = r.get("default")
    if v is None:
        return None
    if r["type"] == "bool":
        return "true" if v else "false"
    if r["type"] == "enum":
        vals = r.get("values") or []
        return vals[v] if 0 <= v < len(vals) else None
    if r["type"] == "float":
        return ("%g" % v)
    return str(v)


for r in rows:
    o = {k: r[k] for k in ("kind", "attr", "member", "type", "offset", "serializer")}
    dv = fmt_default(r)
    if dv is not None:
        o["default"] = dv
    if r.get("values"):
        o["values"] = r["values"]
    vr = {k: r[f] for k, f in (("min", "min_version"), ("max", "max_version")) if f in r}
    if vr:
        o["versions"] = vr
    lines.append("  " + json.dumps(o) + ",")
lines += ["];", ""]
open(OUT, "w", encoding="utf-8", newline="\n").write("\n".join(lines))
print("wrote %s (%d attributes)" % (os.path.normpath(OUT), len(rows)))
